// Package base64 implements gomplate's `base64` template-function namespace.
// Encode uses the standard RFC4648 §4 encoding; Decode and DecodeBytes accept
// both the standard and the URL-safe (RFC4648 §5) padded encodings. When
// both decodings fail, the URL-safe decoder's error is returned, matching the
// reference behaviour. Non-string arguments are coerced to strings: nil
// becomes "", byte slices their string content, and everything else uses
// fmt's %v semantics.
package base64

import (
	stdb64 "encoding/base64"
	"fmt"
)

// NS returns the namespace object whose methods are the `base64` template
// functions.
func NS() any {
	return &ns{}
}

type ns struct{}

func toString(in any) string {
	switch v := in.(type) {
	case nil:
		return ""
	case string:
		return v
	case []byte:
		return string(v)
	}
	return fmt.Sprintf("%v", in)
}

// Encode implements base64.Encode: standard (RFC4648 §4) encoding of the
// input, coerced to a string when necessary.
func (n *ns) Encode(in any) string {
	return stdb64.StdEncoding.EncodeToString([]byte(toString(in)))
}

// decode accepts both standard and URL-safe padded encodings. When both
// fail, the URL-safe decoder's error is the one reported.
func decode(in string) ([]byte, error) {
	b, err := stdb64.StdEncoding.DecodeString(in)
	if err != nil {
		b, err = stdb64.URLEncoding.DecodeString(in)
	}
	return b, err
}

// Decode implements base64.Decode: decodes a standard or URL-safe base64
// string and returns the result as a string.
func (n *ns) Decode(in any) (string, error) {
	b, err := decode(toString(in))
	if err != nil {
		return "", err
	}
	return string(b), nil
}

// DecodeBytes implements base64.DecodeBytes: decodes a standard or URL-safe
// base64 string and returns the result as a byte slice.
func (n *ns) DecodeBytes(in any) ([]byte, error) {
	return decode(toString(in))
}

package base64

import (
	"bytes"
	"testing"
	"text/template"
)

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"base64": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = tt.Execute(&buf, map[string]any{"Env": map[string]string{}})
	return buf.String(), err
}

func TestBase64Funcs(t *testing.T) {
	tests := []struct {
		name    string
		tmpl    string
		want    string
		wantErr string // substring after "error calling <Name>: "
	}{
		// base64.Encode
		{"Encode doc example", `{{ base64.Encode "hello world" }}`, "aGVsbG8gd29ybGQ=", ""},
		{"Encode pipeline", `{{ "hello world" | base64.Encode }}`, "aGVsbG8gd29ybGQ=", ""},
		{"Encode empty", `{{ base64.Encode "" }}`, "", ""},
		{"Encode nil", `{{ base64.Encode nil }}`, "", ""},
		{"Encode standard not url-safe", `{{ base64.Encode "??" }}`, "Pz8=", ""},
		{"Encode binary", `{{ base64.Encode "\x00\x01\xfe\xff" }}`, "AAH+/w==", ""},
		{"Encode int coerced", `{{ base64.Encode 42 }}`, "NDI=", ""},
		{"Encode bool coerced", `{{ base64.Encode true }}`, "dHJ1ZQ==", ""},
		{"Encode float coerced", `{{ base64.Encode 3.14 }}`, "My4xNA==", ""},
		{"Encode float integral coerced", `{{ base64.Encode 2.0 }}`, "Mg==", ""},
		{"Encode map coerced via %v", `{{ base64.Encode (dict "a" 1) }}`, "bWFwW2E6MV0=", ""},
		{"Encode []byte input encodes raw bytes", `{{ base64.DecodeBytes "aGk=" | base64.Encode }}`, "aGk=", ""},
		{"Encode binary []byte round trip", `{{ base64.DecodeBytes "AAH+/w==" | base64.Encode }}`, "AAH+/w==", ""},

		// base64.Decode
		{"Decode doc example", `{{ base64.Decode "aGVsbG8gd29ybGQ=" }}`, "hello world", ""},
		{"Decode pipeline", `{{ "aGVsbG8gd29ybGQ=" | base64.Decode }}`, "hello world", ""},
		{"Decode empty", `{{ base64.Decode "" }}`, "", ""},
		{"Decode short padding", `{{ base64.Decode "aGVsbG8=" }}`, "hello", ""},
		{"Decode url-safe dash", `{{ base64.Decode "-w==" }}`, "\xfb", ""},
		{"Decode url-safe underscore", `{{ base64.Decode "_w==" }}`, "\xff", ""},
		{"Decode standard plus", `{{ base64.Decode "+w==" }}`, "\xfb", ""},
		{"Decode []byte input as string", `{{ base64.DecodeBytes "YUdza1pRPT0=" | base64.Decode }}`, "hk$e", ""},
		{"Decode int coerced then fails", `{{ base64.Decode 42 }}`, "", "illegal base64 data at input byte 0"},
		{"Decode garbage", `{{ base64.Decode "!!!" }}`, "", "illegal base64 data at input byte 0"},
		{"Decode unpadded fails", `{{ base64.Decode "aGVsbG8" }}`, "", "illegal base64 data at input byte 4"},
		{"Decode unpadded url-safe fails", `{{ base64.Decode "-w" }}`, "", "illegal base64 data at input byte 0"},
		{"Decode both fail, url error reported (dash before plus)", `{{ base64.Decode "AB-CD+" }}`, "", "illegal base64 data at input byte 5"},
		{"Decode both fail, url error reported (plus before dash)", `{{ base64.Decode "AB+CD-" }}`, "", "illegal base64 data at input byte 2"},
		{"Decode both fail at padding", `{{ base64.Decode "AAAAAAAA/w" }}`, "", "illegal base64 data at input byte 8"},

		// base64.DecodeBytes
		{"DecodeBytes doc example", `{{ base64.DecodeBytes "aGVsbG8gd29ybGQ=" }}`, "[104 101 108 108 111 32 119 111 114 108 100]", ""},
		{"DecodeBytes empty", `{{ base64.DecodeBytes "" }}`, "[]", ""},
		{"DecodeBytes url-safe", `{{ base64.DecodeBytes "-w==" }}`, "[251]", ""},
		{"DecodeBytes pipeline to conv-like use", `{{ base64.DecodeBytes "aGk=" | base64.Encode | base64.Decode }}`, "hi", ""},
		{"DecodeBytes garbage", `{{ base64.DecodeBytes "!!!" }}`, "", "illegal base64 data at input byte 0"},
		{"DecodeBytes int coerced then fails", `{{ base64.DecodeBytes 42 }}`, "", "illegal base64 data at input byte 0"},
		{"DecodeBytes unpadded fails", `{{ base64.DecodeBytes "aGVsbG8" }}`, "", "illegal base64 data at input byte 4"},
		{"DecodeBytes both fail, url error reported", `{{ base64.DecodeBytes "AB-CD+" }}`, "", "illegal base64 data at input byte 5"},

		// argument-count errors surface from text/template itself
		{"Encode no args", `{{ base64.Encode }}`, "", "wrong number of args for Encode: want 1 got 0"},
		{"Encode two args", `{{ base64.Encode "a" "b" }}`, "", "wrong number of args for Encode: want 1 got 2"},
		{"Decode no args", `{{ base64.Decode }}`, "", "wrong number of args for Decode: want 1 got 0"},
		{"Decode two args", `{{ base64.Decode "a" "b" }}`, "", "wrong number of args for Decode: want 1 got 2"},
		{"DecodeBytes no args", `{{ base64.DecodeBytes }}`, "", "wrong number of args for DecodeBytes: want 1 got 0"},
		{"DecodeBytes two args", `{{ base64.DecodeBytes "a" "b" }}`, "", "wrong number of args for DecodeBytes: want 1 got 2"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := render(t, tt.tmpl)
			if tt.wantErr != "" {
				if err == nil {
					t.Fatalf("expected error containing %q, got nil (output %q)", tt.wantErr, got)
				}
				if !bytes.Contains([]byte(err.Error()), []byte(tt.wantErr)) {
					t.Fatalf("error %q does not contain %q", err.Error(), tt.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got != tt.want {
				t.Fatalf("got %q, want %q", got, tt.want)
			}
		})
	}
}

