fmap := template.FuncMap{
	"base64": func() any { return NS() },
	// minimal dict helper for coercion tests
	"dict": func(kv ...any) (map[string]any, error) {
		m := map[string]any{}
		for i := 0; i < len(kv); i += 2 {
			k, ok := kv[i].(string)
			if !ok {
				return nil, template.ExecError{}
			}
			m[k] = kv[i+1]
		}
		return m, nil
	},
}

